Gemma4RemoteMTPInput.swift.after:
let verificationDepth = try Gemma4RemoteMTPDepth(maximumDraftTokens:local.job.maximumDraftTokens)
let producerRefillPolicy = try Gemma4RemoteMTPRefillPolicy(explicitPolicy:job.refillPolicy,
    verificationDepth:verificationDepth.maximumDraftTokens)

if producerRefillPolicy != .paired {
    report["producerRefillPolicy"] = producerRefillPolicy.rawValue
    report["maximumProducerRefillGrant"] = 1
    report["maximumProducerLookaheadGrant"] = 2
}
if let policy = local.targetProjectionPolicy { report["targetProjectionPolicy"] = policy }

Gemma4MTPPullTarget.swift.after:
let count = try producerRefillPolicy.exposedGrant(draftCount:draftCount,
    proposalCredit:ledger.proposalCredit)
try grant(count,check:check)
